solution:
fn main() -> Int {
  let month = 7;
  let season = match month {
    12 | 1 | 2 => "Winter",
    3 | 4 | 5 => "Spring",
    6 | 7 | 8 => "Summer",
    9 | 10 | 11 => "Fall",
    _ => "Unknown",
  };
  io.println(season);
  return 0;
}
